$nodeScript = @'
const { chromium } = require('playwright')
;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1920, height: 1110 }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  await page.goto('http://localhost:8101/', { waitUntil: 'domcontentloaded', timeout: 30000 })
  await page.waitForTimeout(3000)
  const result = await page.evaluate(() => ({
    url: location.href,
    title: document.title,
    navbar: document.querySelector('.navbar')?.innerText || '',
    items: [...document.querySelectorAll('.top-nav .nav-item')].map(item => ({
      text: item.innerText,
      width: Math.round(item.getBoundingClientRect().width),
      iconCount: item.querySelectorAll('svg,i,img').length
    }))
  }))
  const navbar = await page.$('.navbar')
  if (navbar) await navbar.screenshot({ path: 'e2e/artifacts/task2468-before-navbar.png' })
  console.log(JSON.stringify({ ...result, errors }, null, 2))
  await browser.close()
})().catch(error => { console.error(error); process.exit(1) })
'@
